#include <stdio.h>
#include <stdlib.h>

int compare_long(const void *a, const void *b) {
    long la = *(const long *)a;
    long lb = *(const long *)b;
    if (la < lb) return -1;
    if (la > lb) return 1;
    return 0;
}

int main(int argc, char **argv) {
    if (argc <= 1) {
        puts("EMPTY");
        return 0;
    }
    int n = argc - 1;
    long *values = malloc(n * sizeof(long));
    if (!values) return 1; // allocation failure
    for (int i = 0; i < n; ++i) {
        char *endptr;
        values[i] = strtol(argv[i + 1], &endptr, 10);
        // The original program does not handle errors; we mimic that behavior.
        (void)endptr; // suppress unused warning
    }
    qsort(values, n, sizeof(long), compare_long);
    for (int i = 0; i < n; ++i) {
        printf("%ld", values[i]);
        if (i != n - 1) putchar(' ');
    }
    putchar('\n');
    free(values);
    return 0;
}
